item.aggregated_output:
300	            guard let state = statesByHostID[host.id] else {
301	                return [DockHostIdentityObservation]()
302	            }
303	            let hostObservations = state.streamHosts.map { streamHost in
304	                DockHostIdentityObservation(configuredHostID: host.id, streamHost: streamHost)
305	            }
306	            let cardObservations = state.cardsByID.values.map { card in
307	                DockHostIdentityObservation(configuredHostID: host.id, card: card)
308	            }
309	            return hostObservations + cardObservations
310	        }
311	    }
