321	    private func hostStatus(
322	        freshness: DockStreamFreshnessDTO?,
323	        rowCount: Int,
324	        complete: Bool,
325	        totalRows: Int?
326	    ) -> DockHostLoadStatus {
327	        if !complete {
328	            let visibleRows = rowCount
329	            let knownTotal = max(totalRows ?? visibleRows, visibleRows)
330	            let message = knownTotal > visibleRows
331	                ? "Showing \(visibleRows) of \(knownTotal)"
332	                : "Partial window"
333	            return .partial(rowCount: visibleRows, message: message)
334	        }
335	        guard let freshness else {
336	            return rowCount == 0 ? .checking : .loaded(rowCount: rowCount)
337	        }
338	        switch freshness.status {
339	        case .fresh:
340	            return rowCount == 0 ? .empty : .loaded(rowCount: rowCount)
341	        case .stale:
342	            return .partial(rowCount: rowCount, message: freshness.lastError ?? "Stale")
343	        case .offline:
344	            let message = freshness.lastError ?? "Offline"
345	            return rowCount > 0 ? .partial(rowCount: rowCount, message: "Offline: \(message)") : .offline(message)
346	        case .error:
347	            let message = freshness.lastError ?? "Error"
348	            return rowCount > 0 ? .partial(rowCount: rowCount, message: message) : .error(message)
349	        case .unknown:
350	            return rowCount == 0 ? .checking : .partial(rowCount: rowCount, message: "Refreshing")
351	        }
352	    }
